#!/usr/bin/env sh
# Rebuilds the WebAssembly GEMM kernel and embeds it in gemm-wasm.ts.
# Needs clang and wasm-ld (LLVM 15+).
set -e
cd "$(dirname "$0")"
clang --target=wasm32 -O3 -msimd128 -nostdlib -fno-builtin \
  -Wl,--no-entry -Wl,--import-memory -Wl,--export-dynamic -Wl,--strip-all \
  -o /tmp/shanverse-gemm.wasm gemm.c
B64=$(base64 -w0 /tmp/shanverse-gemm.wasm)
cat > ../../src/features/games/go/katago/gemm-wasm.ts <<TS
// Generated by scripts/go/build-gemm.sh from scripts/go/gemm.c. Do not edit.
export const GEMM_WASM_BASE64 = "$B64";
TS
echo "gemm.wasm: $(wc -c < /tmp/shanverse-gemm.wasm) bytes"
